const std = @import("std");

const Dog = struct {
    name: []const u8,
    fn speak(self: Dog) void {
        std.debug.print("{s} says Woof!\n", .{self.name});
    }
};

const Cat = struct {
    name: []const u8,
    fn speak(self: Cat) void {
        std.debug.print("{s} says Meow!\n", .{self.name});
    }
};

fn makeSpeak(animal: anytype) void {
    const T = @TypeOf(animal);
    const info = @typeInfo(T);
    if (info != .Struct) @compileError("Expected a struct");
    animal.speak();
}

pub fn main() !void {
    const dog = Dog{ .name = "Buddy" };
    const cat = Cat{ .name = "Whiskers" };
    makeSpeak(dog);
    makeSpeak(cat);
}
